(2, 'IOT', '智能水务抄表系统 V1.3', '面向水务公司的远程抄表与阶梯计费平台，含设备接入、计费、账单推送', '2', '张三', 'ACTIVE', '2026-09-08 14:00:00', '2026-09-08 14:00:00');
INSERT INTO test_point (id, project_id, module, point_no, title, description, priority, risk_level, status, source_type, creator_id, creator_name, created_at, updated_at) VALUES
(1, 1, '用户中心', 'TP-MALL-001', '手机号短信验证码注册', '输入未注册手机号，获取 6 位验证码后提交注册，校验验证码有效期、重发频次与手机号格式', 'HIGH', 'HIGH', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(2, 1, '用户中心', 'TP-MALL-002', '账号密码登录失败次数锁定', '连续 5 次密码错误锁定 30 分钟，锁定期间正确密码也不可登录，第 6 次提示剩余时间', 'HIGH', 'HIGH', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(3, 1, '商品中心', 'TP-MALL-003', '商品关键词搜索', '支持商品名、品牌、类目混合检索，校验分词命中、排序规则与空结果提示', 'MEDIUM', 'MEDIUM', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(4, 1, '商品中心', 'TP-MALL-004', '商品详情库存展示', '详情页库存与 SKU 库存一致，库存为 0 时按钮置灰且不可下单', 'HIGH', 'MEDIUM', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(5, 1, '购物车', 'TP-MALL-005', '加入购物车库存校验', '加购数量不得超过可用库存，超过时提示并回退，重复加购需合并数量', 'HIGH', 'HIGH', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(6, 1, '订单中心', 'TP-MALL-006', '提交订单库存扣减', '下单成功扣减库存，并发下单不允许超卖，库存不足时订单创建失败并释放锁定', 'HIGH', 'HIGH', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(7, 1, '订单中心', 'TP-MALL-007', '订单超时自动取消', '未支付订单 30 分钟自动取消并回补库存，取消后不可再支付', 'HIGH', 'HIGH', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(8, 1, '支付中心', 'TP-MALL-008', '微信支付异步回调', '回调验签、幂等处理、金额一致性校验，重复回调不得重复入账', 'HIGH', 'HIGH', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(9, 1, '支付中心', 'TP-MALL-009', '退款原路返回', '退款金额不得超过实付金额，退款后订单状态与账单同步更新', 'HIGH', 'HIGH', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(10, 1, '售后中心', 'TP-MALL-010', '仅退款申请', '已发货未签收订单可申请仅退款，需商家审核，超时自动同意', 'MEDIUM', 'MEDIUM', 'READY', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(11, 1, '消息中心', 'TP-MALL-011', '订单状态变更通知', '订单支付、发货、签收节点触发短信与站内信，内容含订单号与金额', 'LOW', 'LOW', 'DRAFT', 'REQUIREMENT', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(12, 1, '权限安全', 'TP-MALL-012', '水平越权访问他人订单', '普通用户携带他人订单号查询订单详情，应返回 403 而非数据', 'HIGH', 'HIGH', 'READY', 'SECURITY', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(13, 1, '性能', 'TP-MALL-013', '秒杀下单并发能力', '500 并发下单，成功率不低于 99%，P95 响应时间小于 800ms', 'HIGH', 'HIGH', 'DRAFT', 'PERFORMANCE', 1, '王童博', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(14, 2, '设备接入', 'TP-IOT-001', 'NB-IoT 水表数据上报', '设备上报报文解析、重复报文去重、脏数据过滤与告警', 'HIGH', 'HIGH', 'READY', 'REQUIREMENT', 2, '张三', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(15, 2, '计费中心', 'TP-IOT-002', '阶梯水价计费', '按月累计用水量分段计价，跨档位金额按段累加，边界值精准', 'HIGH', 'HIGH', 'READY', 'REQUIREMENT', 2, '张三', '2026-09-10 10:00:00', '2026-09-12 10:00:00'),
(16, 2, '账单推送', 'TP-IOT-003', '月度账单推送', '每月 1 日生成账单并推送短信，失败重试 3 次并记录', 'MEDIUM', 'MEDIUM', 'DRAFT', 'REQUIREMENT', 2, '张三', '2026-09-10 10:00:00', '2026-09-12 10:00:00');
INSERT INTO test_case (id, project_id, test_point_id, case_no, title, precondition, steps, expected_result, priority, case_type, design_method, status, auto_flag, creator_id, creator_name, created_at, updated_at) VALUES
(1, 1, 1, 'TC-MALL-001', '未注册手机号获取验证码后完成注册', '手机号 13900001111 未注册；短信服务正常', '["1. 进入注册页，输入手机号 13900001111","2. 点击获取验证码","3. 输入收到的 6 位验证码","4. 设置密码 Abc@1234 并提交"]', '["注册成功，跳转登录页","数据库 sys_user 新增一条记录，手机号正确","收到注册成功短信"]', 'HIGH', 'FUNCTION', 'EQUIVALENCE', 'READY', 0, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(2, 1, 1, 'TC-MALL-002', '已注册手机号重复注册被拒绝', '手机号 13800000001 已注册', '["1. 进入注册页","2. 输入已注册手机号 13800000001","3. 提交注册"]', '["提示：该手机号已注册，请直接登录","不产生新的用户记录"]', 'HIGH', 'FUNCTION', 'EQUIVALENCE', 'READY', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(3, 1, 1, 'TC-MALL-003', '验证码 60 秒内重复获取被限流', '已获取一次验证码，未超过 60 秒', '["1. 点击获取验证码","2. 立即再次点击获取验证码"]', '["第二次提示：请 47 秒后重试","短信网关仅收到 1 条下发请求"]', 'MEDIUM', 'FUNCTION', 'BOUNDARY', 'READY', 0, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(4, 1, 2, 'TC-MALL-004', '连续 5 次密码错误后账号锁定', '账号 wtb 未锁定', '["1. 连续 5 次输入错误密码登录","2. 第 6 次输入正确密码登录"]', '["第 5 次后提示账号锁定 30 分钟","第 6 次正确密码仍提示已锁定并显示剩余时间"]', 'HIGH', 'FUNCTION', 'BOUNDARY', 'READY', 0, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(5, 1, 2, 'TC-MALL-005', '锁定到期后可正常登录', '账号 wtb 锁定时间已过 30 分钟', '["1. 输入正确密码登录"]', '["登录成功，锁定计数清零"]', 'MEDIUM', 'FUNCTION', 'EQUIVALENCE', 'READY', 0, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(6, 1, 3, 'TC-MALL-006', '按商品名关键词搜索返回匹配结果', '商品库中存在「华为 Mate 60 Pro」', '["1. 搜索框输入「Mate 60」","2. 点击搜索"]', '["结果包含「华为 Mate 60 Pro」","结果按销量降序排列"]', 'MEDIUM', 'FUNCTION', 'EQUIVALENCE', 'READY', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(7, 1, 3, 'TC-MALL-007', '搜索空结果展示友好提示', '商品库中不存在对应商品', '["1. 搜索框输入「zzzzzz」","2. 点击搜索"]', '["展示「没有找到相关商品」","推荐热销商品列表"]', 'LOW', 'FUNCTION', 'BOUNDARY', 'READY', 0, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(8, 1, 4, 'TC-MALL-008', '库存为 0 的商品详情按钮置灰', '商品 A 库存 0', '["1. 打开商品 A 详情页"]', '["加入购物车按钮置灰","点击无响应，提示库存不足"]', 'HIGH', 'UI', 'EQUIVALENCE', 'READY', 0, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(9, 1, 5, 'TC-MALL-009', '加购数量超过库存时被拦截', '商品 A 库存 3', '["1. 商品详情页输入数量 5","2. 点击加入购物车"]', '["提示：库存不足，当前仅剩 3 件","购物车数量不变"]', 'HIGH', 'FUNCTION', 'BOUNDARY', 'READY', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(10, 1, 5, 'TC-MALL-010', '同一商品重复加购数量合并', '商品 A 已在购物车，数量 2', '["1. 再次加入商品 A，数量 2"]', '["购物车中商品 A 数量为 4，不新增行"]', 'MEDIUM', 'FUNCTION', 'EQUIVALENCE', 'READY', 0, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(11, 1, 6, 'TC-MALL-011', '库存充足时下单扣减库存', '商品 A 库存 10，用户已登录', '["1. 加购商品 A 数量 2","2. 提交订单并支付"]', '["订单创建成功","商品 A 库存变为 8","订单状态为待发货"]', 'HIGH', 'FUNCTION', 'EQUIVALENCE', 'READY', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(12, 1, 6, 'TC-MALL-012', '并发下单不出现超卖', '商品 B 库存 1，200 个用户并发下单', '["1. 使用 JMeter 200 线程同时提交订单"]', '["仅 1 个订单创建成功","其余返回库存不足","库存最终为 0，无负数"]', 'HIGH', 'PERFORMANCE', 'SCENARIO', 'READY', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(13, 1, 7, 'TC-MALL-013', '未支付订单 30 分钟自动取消', '订单已创建，状态待支付', '["1. 等待 30 分钟不支付","2. 查询订单状态"]', '["订单状态变为已取消","库存回补 +2","再支付提示订单已关闭"]', 'HIGH', 'FUNCTION', 'BOUNDARY', 'READY', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(14, 1, 8, 'TC-MALL-014', '微信支付回调重复通知幂等', '订单已支付成功', '["1. 模拟微信重复回调 3 次"]', '["仅第一次入账","重复回调返回 SUCCESS 但不再变更订单","账户余额只增加一次"]', 'HIGH', 'INTERFACE', 'SCENARIO', 'READY', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(15, 1, 9, 'TC-MALL-015', '退款金额超过实付金额被拒绝', '订单实付 199.00 元，已申请退款 199.00 元', '["1. 再次申请退款 0.01 元"]', '["提示：退款金额超出可退余额","不生成退款单"]', 'HIGH', 'FUNCTION', 'BOUNDARY', 'READY', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(16, 1, 10, 'TC-MALL-016', '已发货订单申请仅退款需商家审核', '订单状态已发货未签收', '["1. 提交仅退款申请，原因「不想要了」"]', '["售后单状态为待审核","商家端收到待处理提醒"]', 'MEDIUM', 'FUNCTION', 'EQUIVALENCE', 'READY', 0, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(17, 1, 12, 'TC-MALL-017', '普通用户越权查询他人订单', '用户 A 登录，持有用户 B 的订单号', '["1. 调用 GET /api/v1/order/{B的订单号}"]', '["返回 403 无权限","日志记录越权访问告警"]', 'HIGH', 'SECURITY', 'SCENARIO', 'READY', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(18, 1, 13, 'TC-MALL-018', '秒杀场景 500 并发下单成功率', '秒杀商品库存 100，500 并发', '["1. JMeter 500 并发持续 60 秒","2. 统计成功率与响应时间"]', '["成功率 ≥ 99%","P95 响应时间 < 800ms","超卖数为 0"]', 'HIGH', 'PERFORMANCE', 'SCENARIO', 'DRAFT', 1, 1, '王童博', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(19, 2, 14, 'TC-IOT-001', '重复上报报文去重', '设备 D001 已上报报文 Seq=100', '["1. 重复上报 Seq=100 的报文"]', '["第二次被丢弃，记录去重日志","用水量不重复累加"]', 'HIGH', 'FUNCTION', 'EQUIVALENCE', 'READY', 1, 2, '李四', '2026-09-12 14:00:00', '2026-09-15 16:00:00'),
(20, 2, 15, 'TC-IOT-002', '阶梯水价跨档计费准确', '用户本月已用水 18 吨，阶梯第一档 0-20 吨', '["1. 再上报 5 吨用水"]', '["前 2 吨按 2.80 元/吨，后 3 吨按 4.20 元/吨","总费用 18.20 元"]', 'HIGH', 'FUNCTION', 'BOUNDARY', 'READY', 1, 2, '李四', '2026-09-12 14:00:00', '2026-09-15 16:00:00');
