INSERT INTO defect (id, project_id, case_id, execution_id, defect_no, title, description, severity, priority, status, assignee_id, assignee_name, reporter_id, reporter_name, resolved_at, created_at, updated_at) VALUES
(1, 1, 13, NULL, 'BUG-MALL-001', '未支付订单超过 30 分钟未被自动取消', '订单创建后 31 分钟查询仍为待支付状态，库存未回补。定时任务 cron 配置为 0 0/5 * * * ?，但上次执行抛出 NullPointerException。', 'CRITICAL', 'HIGH', 'RESOLVED', 4, '王五', 1, '王童博', '2026-09-26 15:00:00', '2026-09-25 10:30:00', '2026-09-26 15:00:00'),
(2, 1, 12, NULL, 'BUG-MALL-002', '并发下单出现超卖，库存为负', '200 并发下商品 B 创建了 3 个订单，库存变为 -2。库存扣减使用先查后改，未加行锁。', 'BLOCKER', 'HIGH', 'RESOLVED', 4, '王五', 1, '王童博', '2026-09-28 11:00:00', '2026-09-27 16:20:00', '2026-09-28 11:00:00'),
(3, 1, 14, NULL, 'BUG-MALL-003', '微信重复回调导致重复入账', '同一笔订单收到 2 次回调后用户余额增加两次，缺少幂等键校验。', 'CRITICAL', 'HIGH', 'FIXING', 4, '王五', 1, '王童博', NULL, '2026-10-08 14:10:00', '2026-10-09 09:00:00'),
(4, 1, 15, NULL, 'BUG-MALL-004', '退款金额校验缺失，可超额退款', '已全额退款后仍可发起 0.01 元退款，且生成退款单。', 'MAJOR', 'HIGH', 'OPEN', 4, '王五', 1, '王童博', NULL, '2026-10-09 10:05:00', '2026-10-09 10:05:00'),
(5, 1, 9, NULL, 'BUG-MALL-005', '加购数量超过库存时提示文案错误', '提示「商品已下架」而非「库存不足」，前端错误码映射缺失。', 'MINOR', 'LOW', 'CLOSED', 4, '王五', 3, '李四', '2026-09-30 17:00:00', '2026-09-29 11:40:00', '2026-09-30 17:00:00'),
(6, 1, 7, NULL, 'BUG-MALL-006', '搜索无结果页推荐位为空', '搜索 zzzzzz 后推荐商品区域空白，接口返回 500。', 'MAJOR', 'MEDIUM', 'RESOLVED', 4, '王五', 3, '李四', '2026-10-02 10:00:00', '2026-10-01 15:30:00', '2026-10-02 10:00:00'),
(7, 1, 17, NULL, 'BUG-MALL-007', '普通用户可越权查询他人订单', '携带他人订单号调用订单详情接口返回完整数据，应返回 403。', 'CRITICAL', 'HIGH', 'OPEN', 4, '王五', 1, '王童博', NULL, '2026-10-10 09:30:00', '2026-10-10 09:30:00'),
(8, 1, NULL, NULL, 'BUG-MALL-008', '商品详情页库存与 SKU 库存不一致', '详情页显示 10 件，选择规格后显示 0 件，缓存未按 SKU 维度隔离。', 'MAJOR', 'MEDIUM', 'FIXING', 4, '王五', 3, '李四', NULL, '2026-10-11 16:00:00', '2026-10-12 09:00:00'),
(9, 2, 19, NULL, 'BUG-IOT-001', '重复报文未去重导致水量翻倍', '设备重传 Seq=100 报文后水量累加两次。', 'MAJOR', 'HIGH', 'RESOLVED', 4, '王五', 2, '张三', '2026-10-12 14:00:00', '2026-10-11 10:00:00', '2026-10-12 14:00:00'),
